svg.script:
function show_8ddaaf81(evt, text) {
	var pos = (evt.target.getAttribute("y") < 1699) ? "bottom" : "top";
	var note = document.getElementById(pos + "_note_8ddaaf81");
	note.textContent = text;
	note.setAttributeNS(null, "visibility", "visible");
	document.getElementById(pos + "_overlay_8ddaaf81").setAttributeNS(null, "visibility", "visible");
}
function hide_8ddaaf81(evt) {
	document.getElementById("top_note_8ddaaf81").setAttributeNS(null, "visibility", "hidden");
	document.getElementById("top_overlay_8ddaaf81").setAttributeNS(null, "visibility", "hidden");
	document.getElementById("bottom_note_8ddaaf81").setAttributeNS(null, "visibility", "hidden");
	document.getElementById("bottom_overlay_8ddaaf81").setAttributeNS(null, "visibility", "hidden");
}
